mapper.select:
SELECT p.id, p.plate_no AS plateNo, p.park_fee AS parkFee, p.status, p.check_time AS checkTime, p.station_id AS stationId, s.name AS stationName, u.nickname AS checkUserName, p.check_result AS checkResult, p.remark, p.reserve1, p.reserve2, p.creator, p.updater, p.create_time AS createTime, p.update_time AS updateTime FROM pay_check p LEFT JOIN station_info s ON p.station_id = s.id AND s.deleted = 0 LEFT JOIN user_info u ON p.check_user_id = u.id AND u.deleted = 0 WHERE p.deleted = 0
AND p.plate_no LIKE CONCAT('%', #{reqVO.plateNo}, '%')
AND p.park_fee = #{reqVO.parkFee}
AND p.status = #{reqVO.status}
AND p.check_time BETWEEN #{reqVO.checkTime[0]} AND #{reqVO.checkTime[1]}
AND p.station_id = #{reqVO.stationId}
AND s.name LIKE CONCAT('%', #{reqVO.stationName}, '%')
AND p.check_user_id = #{reqVO.checkUserId}
AND u.nickname LIKE CONCAT('%', #{reqVO.checkUserName}, '%')
AND p.check_result LIKE CONCAT('%', #{reqVO.checkResult}, '%')
AND p.remark LIKE CONCAT('%', #{reqVO.remark}, '%')
ORDER BY p.id DESC
